private int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index < headerPart.length() && headerPart.charAt(index) != '\r') {
        index++;
    }
    if (index == headerPart.length() - 1) {
        return index;
    } else if (headerPart.charAt(index) == '\r' && headerPart.charAt(index + 1) == '\n') {
        return index + 2;
    } else {
        throw new IllegalArgumentException("Invalid header part: " + headerPart);
    }
}

