public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Step 1: Check if the box is valid
    if (box == null || box.width <= 0) {
        throw new IllegalArgumentException("Invalid box: " + box);
    }

    // Step 2: Calculate the coordinates of the midpoint and split the box
    double midpoint = box.center.x - (box.width / 2);
    Box2D leftBox = new Box2D(box.center.x, box.center.y, box.width / 2, box.height);
    Box2D rightBox = new Box2D(midpoint, box.center.y, midpoint, box.height);

    // Step 3: Return the resulting boxes
    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double x = box.getX();
    double y = box.getY();
    double width = box.getWidth();
    double height = box.getHeight();
    double halfWidth = width / 2;
    double x1 = x + halfWidth;

    Box2D box1 = new Box2D(x, y, halfWidth, height);
    Box2D box2 = new Box2D(x1, y, width - halfWidth, height);

    return new Pair<>(box1, box2);
}

