private void pop(final String descriptor) {
    // Split the descriptor into individual type or method descriptors
    final String[] descriptors = descriptor.split(",");

    // Get the last type or method descriptor
    final String lastDescriptor = descriptors[descriptors.length - 1];

    // Pop the appropriate number of types from the output frame stack
    switch (lastDescriptor.charAt(0)) {
